// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }

    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, type(uint128).max);

        vm.deal(actor, amount);
        vm.startPrank(actor);
        c.deposit{value: amount}();

        // first full withdrawal succeeds (credit == amount > 0)
        c.withdrawAll();

        // RULE: once a full withdrawal has succeeded, a repeat withdrawAll
        // must succeed (credit was cleared); the mutant's stale credit makes
        // it underflow `balance` and revert.
        bool ok;
        try c.withdrawAll() {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        assertTrue(ok);
    }
}
